import{b as d,O as r,g as e,j as n}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"测试术语速查","description":"","frontmatter":{},"headers":[],"relativePath":"testing/appendix/testing-glossary/index.md","filePath":"测试理论与实践/7.附录：模板与核心概念/07.测试术语速查.md","lastUpdated":1781688244000}'),o={name:"testing/appendix/testing-glossary/index.md"};function s(a,t,g,i,h,l){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="测试术语速查" tabindex="-1">测试术语速查 <a class="header-anchor" href="#测试术语速查" aria-label="Permalink to &quot;测试术语速查&quot;">​</a></h1><blockquote><p>覆盖软件测试常用专业术语，中英文对照 + 一句话解释。按维度分类，方便快速定位。</p></blockquote><hr><h2 id="一、测试级别-test-level" tabindex="-1">一、测试级别（Test Level） <a class="header-anchor" href="#一、测试级别-test-level" aria-label="Permalink to &quot;一、测试级别（Test Level）&quot;">​</a></h2><p>回答&quot;测多大范围？&quot;，从小到大排列：</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>单元测试</strong></td><td>Unit Test</td><td>测单个函数/类/方法，毫秒级，开发写</td></tr><tr><td><strong>集成测试</strong></td><td>Integration Test</td><td>测模块间交互、接口调用，需要数据库/网络</td></tr><tr><td><strong>接口测试</strong></td><td>API Test</td><td>测接口的请求/响应、异常码、边界值，属于集成测试</td></tr><tr><td><strong>系统测试</strong></td><td>System Test</td><td>测完整系统端到端，需要完整部署环境</td></tr><tr><td><strong>验收测试</strong></td><td>Acceptance Test</td><td>确认系统满足业务需求，由产品/用户执行</td></tr><tr><td><strong>α 测试</strong></td><td>Alpha Test</td><td>内部团队在受控环境中做验收测试</td></tr><tr><td><strong>β 测试</strong></td><td>Beta Test</td><td>真实外部用户在其环境中试用</td></tr><tr><td><strong>UAT</strong></td><td>User Acceptance Test</td><td>客户/甲方按验收标准逐条确认</td></tr><tr><td><strong>端到端测试</strong></td><td>End-to-End Test (E2E)</td><td>从用户视角测完整业务链路</td></tr></tbody></table><hr><h2 id="二、测试目的-test-purpose" tabindex="-1">二、测试目的（Test Purpose） <a class="header-anchor" href="#二、测试目的-test-purpose" aria-label="Permalink to &quot;二、测试目的（Test Purpose）&quot;">​</a></h2><p>回答&quot;这一轮为什么测？&quot;：</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>冒烟测试</strong></td><td>Smoke Test</td><td>快速验证核心流程能否走通，5~30 分钟，不通过就打回</td></tr><tr><td><strong>回归测试</strong></td><td>Regression Test</td><td>改完代码后确认旧功能没被搞坏</td></tr><tr><td><strong>探索式测试</strong></td><td>Exploratory Test</td><td>边测边学边设计用例，不按预设脚本</td></tr><tr><td><strong>基准测试</strong></td><td>Benchmark Test</td><td>在固定条件下重复跑，建立性能参照线</td></tr><tr><td><strong>重测/确认测试</strong></td><td>Retest / Confirmation Test</td><td>验证之前失败的用例修好没</td></tr><tr><td><strong>猴子测试</strong></td><td>Monkey Test</td><td>随机输入/操作，看系统会不会崩溃</td></tr><tr><td><strong>健全测试</strong></td><td>Sanity Test</td><td>验证某个修复或新功能的特定行为是否正常，比冒烟更窄</td></tr></tbody></table><hr><h2 id="三、测试类型-test-type" tabindex="-1">三、测试类型（Test Type） <a class="header-anchor" href="#三、测试类型-test-type" aria-label="Permalink to &quot;三、测试类型（Test Type）&quot;">​</a></h2><p>回答&quot;关注什么质量属性？&quot;：</p><h3 id="_3-1-功能类" tabindex="-1">3.1 功能类 <a class="header-anchor" href="#_3-1-功能类" aria-label="Permalink to &quot;3.1 功能类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>功能测试</strong></td><td>Functional Test</td><td>验证需求里的功能有没有正确实现</td></tr><tr><td><strong>可用性测试</strong></td><td>Usability Test</td><td>用户能不能轻松完成任务</td></tr><tr><td><strong>可访问性测试</strong></td><td>Accessibility Test (A11y)</td><td>残障人士能不能正常使用</td></tr><tr><td><strong>本地化测试</strong></td><td>Localization Test (L10n)</td><td>软件适应特定语言/地区的程度</td></tr><tr><td><strong>国际化测试</strong></td><td>Internationalization Test (I18n)</td><td>软件支持多语言/多地区的能力</td></tr></tbody></table><h3 id="_3-2-性能类" tabindex="-1">3.2 性能类 <a class="header-anchor" href="#_3-2-性能类" aria-label="Permalink to &quot;3.2 性能类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>性能测试</strong></td><td>Performance Test</td><td>评估系统在给定负载下的响应速度、稳定性和资源消耗</td></tr><tr><td><strong>负载测试</strong></td><td>Load Test</td><td>在预期负载下测试系统表现</td></tr><tr><td><strong>压力测试</strong></td><td>Stress Test</td><td>超出设计极限，看系统什么时候崩溃、怎么崩溃</td></tr><tr><td><strong>容量测试</strong></td><td>Volume Test</td><td>测试系统能处理的最大数据量</td></tr><tr><td><strong>耐力测试/浸泡测试</strong></td><td>Endurance Test / Soak Test</td><td>长时间持续运行，找内存泄漏等累积问题</td></tr><tr><td><strong>可扩展性测试</strong></td><td>Scalability Test</td><td>系统能不能通过增加资源来应对增长</td></tr><tr><td><strong>峰值测试</strong></td><td>Spike Test</td><td>突然大幅增加/减少负载，看系统反应</td></tr></tbody></table><h3 id="_3-3-安全类" tabindex="-1">3.3 安全类 <a class="header-anchor" href="#_3-3-安全类" aria-label="Permalink to &quot;3.3 安全类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>安全测试</strong></td><td>Security Test</td><td>验证安全机制是否有效：认证、授权、加密、会话管理</td></tr><tr><td><strong>渗透测试</strong></td><td>Penetration Test</td><td>模拟黑客攻击，尝试突破系统防御</td></tr><tr><td><strong>漏洞扫描</strong></td><td>Vulnerability Scan</td><td>用工具自动扫描已知漏洞</td></tr><tr><td><strong>模糊测试</strong></td><td>Fuzz Testing / Fuzzing</td><td>输入大量随机/畸形数据，找崩溃和安全漏洞</td></tr><tr><td><strong>SQL 注入</strong></td><td>SQL Injection</td><td>通过输入恶意 SQL 语句操控数据库</td></tr><tr><td><strong>XSS</strong></td><td>Cross-Site Scripting</td><td>注入恶意脚本到网页，盗取用户信息</td></tr><tr><td><strong>CSRF</strong></td><td>Cross-Site Request Forgery</td><td>伪造用户请求，以用户身份执行非本意操作</td></tr></tbody></table><h3 id="_3-4-其他类型" tabindex="-1">3.4 其他类型 <a class="header-anchor" href="#_3-4-其他类型" aria-label="Permalink to &quot;3.4 其他类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>兼容性测试</strong></td><td>Compatibility Test</td><td>不同环境（浏览器/OS/设备）能不能正常用</td></tr><tr><td><strong>可靠性测试</strong></td><td>Reliability Test</td><td>长时间运行是否稳定，故障概率多大</td></tr><tr><td><strong>可恢复性测试</strong></td><td>Recoverability Test</td><td>出故障后能不能恢复、数据完不完整</td></tr><tr><td><strong>安装测试</strong></td><td>Installation Test</td><td>安装/部署/卸载过程是否正常</td></tr><tr><td><strong>配置测试</strong></td><td>Configuration Test</td><td>不同硬件/软件配置下的表现</td></tr><tr><td><strong>文档测试</strong></td><td>Documentation Test</td><td>用户文档是否准确、能照着操作</td></tr><tr><td><strong>合规性测试</strong></td><td>Compliance Test</td><td>是否符合法律法规和行业标准</td></tr></tbody></table><hr><h2 id="四、测试方法-test-technique" tabindex="-1">四、测试方法（Test Technique） <a class="header-anchor" href="#四、测试方法-test-technique" aria-label="Permalink to &quot;四、测试方法（Test Technique）&quot;">​</a></h2><p>回答&quot;怎么设计用例？怎么看代码？&quot;：</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>黑盒测试</strong></td><td>Black-Box Test</td><td>不看代码，只关心输入输出对不对</td></tr><tr><td><strong>白盒测试</strong></td><td>White-Box Test</td><td>打开代码，确保每条路径都走过</td></tr><tr><td><strong>灰盒测试</strong></td><td>Gray-Box Test</td><td>了解内部结构但不逐行看，知道数据流就行</td></tr><tr><td><strong>等价类划分</strong></td><td>Equivalence Partitioning</td><td>把输入数据分组，每组抽一个代表来测</td></tr><tr><td><strong>边界值分析</strong></td><td>Boundary Value Analysis</td><td>测边界值（最小值、最大值、刚好超出的值）</td></tr><tr><td><strong>决策表测试</strong></td><td>Decision Table Testing</td><td>用表格列出所有条件组合生成用例</td></tr><tr><td><strong>状态转换测试</strong></td><td>State Transition Testing</td><td>画出状态图，测状态间的所有合法/非法跳转</td></tr><tr><td><strong>用例测试</strong></td><td>Use Case Testing</td><td>按用户使用场景设计测试</td></tr><tr><td><strong>结对测试</strong></td><td>Pairwise Testing / All-Pairs</td><td>用最少用例覆盖最多的参数两两组合</td></tr><tr><td><strong>基于风险的测试</strong></td><td>Risk-Based Testing (RBT)</td><td>优先测试风险最高的功能和区域</td></tr><tr><td><strong>基于模型的测试</strong></td><td>Model-Based Testing (MBT)</td><td>从系统模型自动生成测试用例</td></tr></tbody></table><hr><h2 id="五、执行形态-test-execution" tabindex="-1">五、执行形态（Test Execution） <a class="header-anchor" href="#五、执行形态-test-execution" aria-label="Permalink to &quot;五、执行形态（Test Execution）&quot;">​</a></h2><p>回答&quot;人跑还是机器跑？跑不跑代码？&quot;：</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>静态测试</strong></td><td>Static Test</td><td>不运行代码，审查文档/代码，用工具扫</td></tr><tr><td><strong>动态测试</strong></td><td>Dynamic Test</td><td>运行程序，观察实际输出和预期是否一致</td></tr><tr><td><strong>手工测试</strong></td><td>Manual Test</td><td>人来执行测试步骤</td></tr><tr><td><strong>自动化测试</strong></td><td>Automated Test</td><td>脚本/工具来跑，适合重复性场景</td></tr><tr><td><strong>代码审查</strong></td><td>Code Review</td><td>人工检查代码逻辑、规范、潜在缺陷</td></tr><tr><td><strong>静态分析</strong></td><td>Static Analysis</td><td>工具自动扫代码，找规范问题和潜在缺陷</td></tr></tbody></table><hr><h2 id="六、缺陷管理-defect-management" tabindex="-1">六、缺陷管理（Defect Management） <a class="header-anchor" href="#六、缺陷管理-defect-management" aria-label="Permalink to &quot;六、缺陷管理（Defect Management）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>缺陷/Bug</strong></td><td>Defect / Bug</td><td>软件中不符合需求或预期的地方</td></tr><tr><td><strong>严重性</strong></td><td>Severity</td><td>Bug 对系统功能的影响多大（测试定）</td></tr><tr><td><strong>优先级</strong></td><td>Priority</td><td>Bug 应该多快修（产品/项目经理定）</td></tr><tr><td><strong>重现步骤</strong></td><td>Steps to Reproduce</td><td>别人照着做一定能看到同样现象的步骤</td></tr><tr><td><strong>缺陷生命周期</strong></td><td>Defect Life Cycle</td><td>New → Open → In Progress → Fixed → Verified → Closed</td></tr><tr><td><strong>Bug 分类会</strong></td><td>Bug Triage / Bug Council</td><td>测试+开发+产品三方一起过新 Bug，决定修不修、什么时候修</td></tr><tr><td><strong>重开</strong></td><td>Reopen</td><td>验证时发现 Bug 没修好或修出新问题，打回重来</td></tr><tr><td><strong>误报</strong></td><td>False Positive</td><td>报告了一个实际上不是 Bug 的问题</td></tr><tr><td><strong>无法复现</strong></td><td>Cannot Reproduce</td><td>按步骤操作看不到报告的现象</td></tr><tr><td><strong>设计如此</strong></td><td>By Design</td><td>不是 Bug，是故意这么设计的</td></tr><tr><td><strong>重复缺陷</strong></td><td>Duplicate Bug</td><td>和已有 Bug 是同一个问题</td></tr><tr><td><strong>缺陷密度</strong></td><td>Defect Density</td><td>每千行代码/每个模块发现的 Bug 数量</td></tr><tr><td><strong>缺陷发现率</strong></td><td>Defect Detection Rate</td><td>单位时间内发现的新 Bug 数</td></tr><tr><td><strong>重开率</strong></td><td>Reopen Rate</td><td>Reopened 数 / 已修复数，&gt; 10% 表明根因没找准</td></tr><tr><td><strong>Bug 集群效应</strong></td><td>Bug Clustering</td><td>Bug 不是均匀分布的——少数模块集中了大多数 Bug</td></tr></tbody></table><hr><h2 id="七、测试设计-test-design" tabindex="-1">七、测试设计（Test Design） <a class="header-anchor" href="#七、测试设计-test-design" aria-label="Permalink to &quot;七、测试设计（Test Design）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>测试用例</strong></td><td>Test Case</td><td>一组输入、执行条件、预期结果的组合</td></tr><tr><td><strong>测试套件</strong></td><td>Test Suite</td><td>一组测试用例的集合</td></tr><tr><td><strong>测试脚本</strong></td><td>Test Script</td><td>自动化执行的测试步骤</td></tr><tr><td><strong>测试数据</strong></td><td>Test Data</td><td>测试执行前准备好的输入数据</td></tr><tr><td><strong>测试夹具</strong></td><td>Test Fixture</td><td>测试执行前设置的环境和状态</td></tr><tr><td><strong>测试预言</strong></td><td>Test Oracle</td><td>判断测试是否通过的依据（预期结果）</td></tr><tr><td><strong>正向用例</strong></td><td>Positive Test Case</td><td>正常操作，验证系统按预期工作</td></tr><tr><td><strong>负向用例</strong></td><td>Negative Test Case</td><td>异常操作，验证系统正确处理错误</td></tr><tr><td><strong>边界用例</strong></td><td>Boundary Test Case</td><td>测输入域边界值</td></tr></tbody></table><hr><h2 id="八、测试管理-test-management" tabindex="-1">八、测试管理（Test Management） <a class="header-anchor" href="#八、测试管理-test-management" aria-label="Permalink to &quot;八、测试管理（Test Management）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>测试计划</strong></td><td>Test Plan</td><td>回答测什么、怎么测、什么时候测完</td></tr><tr><td><strong>测试策略</strong></td><td>Test Strategy</td><td>整体上用什么方法测、测多深</td></tr><tr><td><strong>测试估算</strong></td><td>Test Estimation</td><td>预估测试需要的时间、人力、资源</td></tr><tr><td><strong>测试监控</strong></td><td>Test Monitoring</td><td>持续跟踪测试进度和计划偏差</td></tr><tr><td><strong>准出标准/退出标准</strong></td><td>Exit Criteria</td><td>什么条件满足了算测完</td></tr><tr><td><strong>准入标准</strong></td><td>Entry Criteria</td><td>什么条件满足了才能开始测</td></tr><tr><td><strong>需求追溯矩阵</strong></td><td>Requirements Traceability Matrix (RTM)</td><td>用例和需求的映射表，确认每个需求都有测到</td></tr><tr><td><strong>测试覆盖率</strong></td><td>Test Coverage</td><td>测了多少，百分比的度量</td></tr><tr><td><strong>代码覆盖率</strong></td><td>Code Coverage</td><td>测试执行时走了多少行/分支/路径的代码</td></tr><tr><td><strong>需求覆盖率</strong></td><td>Requirements Coverage</td><td>多少需求有对应的测试用例</td></tr></tbody></table><hr><h2 id="九、敏捷测试-agile-testing" tabindex="-1">九、敏捷测试（Agile Testing） <a class="header-anchor" href="#九、敏捷测试-agile-testing" aria-label="Permalink to &quot;九、敏捷测试（Agile Testing）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>敏捷测试</strong></td><td>Agile Testing</td><td>跟随迭代节奏持续测试，测试嵌入开发过程</td></tr><tr><td><strong>Scrum</strong></td><td>Scrum</td><td>敏捷框架，固定时间盒（Sprint）迭代交付</td></tr><tr><td><strong>看板</strong></td><td>Kanban</td><td>可视化工作流，限制在制品数量的敏捷方法</td></tr><tr><td><strong>Sprint</strong></td><td>Sprint / Iteration</td><td>一个固定长度的开发周期（通常 1-4 周）</td></tr><tr><td><strong>每日站会</strong></td><td>Daily Standup</td><td>每天 15 分钟，同步进度和阻塞</td></tr><tr><td><strong>用户故事</strong></td><td>User Story</td><td>&quot;作为&lt;角色&gt;，我想要&lt;功能&gt;，以便&lt;价值&gt;&quot;</td></tr><tr><td><strong>验收标准</strong></td><td>Acceptance Criteria</td><td>用户故事完成必须满足的条件</td></tr><tr><td><strong>BDD</strong></td><td>Behavior-Driven Development</td><td>用自然语言描述行为（Given-When-Then），再映射到测试</td></tr><tr><td><strong>TDD</strong></td><td>Test-Driven Development</td><td>先写测试再写代码，红→绿→重构</td></tr><tr><td><strong>ATDD</strong></td><td>Acceptance Test-Driven Development</td><td>先定义验收测试，再驱动开发</td></tr><tr><td><strong>SBTM</strong></td><td>Session-Based Test Management</td><td>以时间盒探索会话为基础的测试管理方法</td></tr><tr><td><strong>测试金字塔</strong></td><td>Test Pyramid</td><td>单元 70% + 集成 20% + 端到端 10% 的分层结构</td></tr><tr><td><strong>测试四象限</strong></td><td>Agile Testing Quadrants</td><td>按业务面/技术面 × 支撑团队/评判产品，划分四类测试</td></tr><tr><td><strong>故事点</strong></td><td>Story Point</td><td>估算用户故事工作量的相对度量</td></tr><tr><td><strong>速度</strong></td><td>Velocity</td><td>团队每个 Sprint 完成的故事点总数</td></tr></tbody></table><hr><h2 id="十、ci-cd-与-devops" tabindex="-1">十、CI/CD 与 DevOps <a class="header-anchor" href="#十、ci-cd-与-devops" aria-label="Permalink to &quot;十、CI/CD 与 DevOps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>持续集成</strong></td><td>Continuous Integration (CI)</td><td>频繁合入代码，自动构建 + 自动跑测试</td></tr><tr><td><strong>持续交付</strong></td><td>Continuous Delivery (CD)</td><td>代码随时可部署到生产，但需人工触发</td></tr><tr><td><strong>持续部署</strong></td><td>Continuous Deployment</td><td>通过测试后自动部署到生产，无需人工干预</td></tr><tr><td><strong>部署管道</strong></td><td>Deployment Pipeline</td><td>从代码提交到生产的一系列自动化阶段</td></tr><tr><td><strong>提交门禁</strong></td><td>Commit Gate</td><td>代码合入前必须通过的自动化检查</td></tr><tr><td><strong>DevOps</strong></td><td>DevOps</td><td>开发+运维协作，打破部门墙，加速交付</td></tr><tr><td><strong>DevSecOps</strong></td><td>DevSecOps</td><td>在 DevOps 流程中嵌入安全测试</td></tr><tr><td><strong>左移</strong></td><td>Shift Left</td><td>测试活动尽早介入，越早发现问题成本越低</td></tr><tr><td><strong>右移</strong></td><td>Shift Right</td><td>在生产环境中持续验证（监控、混沌工程、A/B 测试）</td></tr><tr><td><strong>GitOps</strong></td><td>GitOps</td><td>以 Git 为唯一真实源，声明式管理基础设施和部署</td></tr></tbody></table><hr><h2 id="十一、上线与发布-release-deploy" tabindex="-1">十一、上线与发布（Release &amp; Deploy） <a class="header-anchor" href="#十一、上线与发布-release-deploy" aria-label="Permalink to &quot;十一、上线与发布（Release &amp; Deploy）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>灰度发布</strong></td><td>Gray Release / Dark Launch</td><td>只对一小部分用户放开新版本</td></tr><tr><td><strong>滚动发布</strong></td><td>Rolling Deployment</td><td>逐个/逐批替换实例，新旧短暂共存</td></tr><tr><td><strong>蓝绿部署</strong></td><td>Blue-Green Deployment</td><td>两套完整环境，切换流量即可回滚</td></tr><tr><td><strong>金丝雀发布</strong></td><td>Canary Release</td><td>先放小流量到新版本，监控正常再全量</td></tr><tr><td><strong>功能开关</strong></td><td>Feature Flag / Feature Toggle</td><td>代码部署但功能不开启，用开关控制</td></tr><tr><td><strong>狗粮测试</strong></td><td>Dogfooding</td><td>团队先用自己的产品，内部发现最明显问题</td></tr><tr><td><strong>A/B 测试</strong></td><td>A/B Testing</td><td>两套方案给不同用户组，对比效果——非测试方法，是产品实验</td></tr><tr><td><strong>回滚</strong></td><td>Rollback</td><td>从新版本退回到旧版本</td></tr><tr><td><strong>热修复</strong></td><td>Hotfix</td><td>紧急绕过常规流程修复生产环境问题</td></tr><tr><td><strong>上线复盘</strong></td><td>Release Retrospective</td><td>上线后回顾过程，固化经验，产出改进项</td></tr></tbody></table><hr><h2 id="十二、测试自动化-test-automation" tabindex="-1">十二、测试自动化（Test Automation） <a class="header-anchor" href="#十二、测试自动化-test-automation" aria-label="Permalink to &quot;十二、测试自动化（Test Automation）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>自动化框架</strong></td><td>Test Automation Framework</td><td>自动化测试的组织结构和运行环境</td></tr><tr><td><strong>关键字驱动</strong></td><td>Keyword-Driven Testing</td><td>用自然语言关键字（如&quot;打开浏览器&quot;&quot;输入用户名&quot;）写测试</td></tr><tr><td><strong>数据驱动</strong></td><td>Data-Driven Testing</td><td>测试逻辑不变，数据从外部表/文件读入</td></tr><tr><td><strong>页面对象模型</strong></td><td>Page Object Model (POM)</td><td>每个页面封装为一个对象，操作和定位分离</td></tr><tr><td><strong>Selenium</strong></td><td>Selenium</td><td>Web 自动化测试工具集</td></tr><tr><td><strong>Playwright</strong></td><td>Playwright</td><td>微软开源的多浏览器自动化工具</td></tr><tr><td><strong>Cypress</strong></td><td>Cypress</td><td>前端自动化测试框架，运行在浏览器内</td></tr><tr><td><strong>Appium</strong></td><td>Appium</td><td>移动端自动化测试框架</td></tr><tr><td><strong>JMeter</strong></td><td>Apache JMeter</td><td>性能测试和负载测试工具</td></tr><tr><td><strong>SonarQube</strong></td><td>SonarQube</td><td>静态代码分析平台</td></tr><tr><td><strong>BVT</strong></td><td>Build Verification Test</td><td>构建完成后的快速自动化验证</td></tr><tr><td><strong>无头浏览器</strong></td><td>Headless Browser</td><td>没有 GUI 界面的浏览器，适合 CI 跑自动化</td></tr></tbody></table><hr><h2 id="十三、常见缩写" tabindex="-1">十三、常见缩写 <a class="header-anchor" href="#十三、常见缩写" aria-label="Permalink to &quot;十三、常见缩写&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>全称</th><th>中文</th></tr></thead><tbody><tr><td><strong>QA</strong></td><td>Quality Assurance</td><td>质量保证</td></tr><tr><td><strong>QC</strong></td><td>Quality Control</td><td>质量控制</td></tr><tr><td><strong>SDET</strong></td><td>Software Development Engineer in Test</td><td>测试开发工程师</td></tr><tr><td><strong>SUT</strong></td><td>System Under Test</td><td>被测系统</td></tr><tr><td><strong>AUT</strong></td><td>Application Under Test</td><td>被测应用</td></tr><tr><td><strong>P0/P1/P2/P3</strong></td><td>Priority 0/1/2/3</td><td>优先级 0-3 级</td></tr><tr><td><strong>P95/P99</strong></td><td>95th/99th Percentile</td><td>第 95/99 百分位响应时间</td></tr><tr><td><strong>SLA</strong></td><td>Service Level Agreement</td><td>服务等级协议</td></tr><tr><td><strong>SLO</strong></td><td>Service Level Objective</td><td>服务等级目标</td></tr><tr><td><strong>SLI</strong></td><td>Service Level Indicator</td><td>服务等级指标</td></tr><tr><td><strong>MTTR</strong></td><td>Mean Time to Recover</td><td>平均恢复时间</td></tr><tr><td><strong>MTBF</strong></td><td>Mean Time Between Failures</td><td>平均故障间隔时间</td></tr><tr><td><strong>RCA</strong></td><td>Root Cause Analysis</td><td>根因分析</td></tr><tr><td><strong>KPI</strong></td><td>Key Performance Indicator</td><td>关键绩效指标</td></tr><tr><td><strong>DORA</strong></td><td>DevOps Research and Assessment</td><td>衡量 DevOps 效率的四个指标（部署频率、变更前置时间、故障恢复时间、变更失败率）</td></tr><tr><td><strong>RBT</strong></td><td>Risk-Based Testing</td><td>基于风险的测试</td></tr><tr><td><strong>SBTM</strong></td><td>Session-Based Test Management</td><td>基于会话的测试管理</td></tr><tr><td><strong>RTE</strong></td><td>Real-Time Embedded</td><td>实时嵌入式系统</td></tr><tr><td><strong>IoT</strong></td><td>Internet of Things</td><td>物联网</td></tr><tr><td><strong>AI/ML</strong></td><td>Artificial Intelligence / Machine Learning</td><td>人工智能/机器学习</td></tr></tbody></table><hr><h2 id="十四、其他常用术语" tabindex="-1">十四、其他常用术语 <a class="header-anchor" href="#十四、其他常用术语" aria-label="Permalink to &quot;十四、其他常用术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话</th></tr></thead><tbody><tr><td><strong>验证</strong></td><td>Verification</td><td>检查产品是否按规定的方式构建（&quot;做对了吗？&quot;）</td></tr><tr><td><strong>确认</strong></td><td>Validation</td><td>检查构建的产品是否符合需求（&quot;做了对的东西吗？&quot;）</td></tr><tr><td><strong>测试基</strong></td><td>Test Basis</td><td>测试用例/条件的来源（需求文档、设计文档、代码）</td></tr><tr><td><strong>测试件</strong></td><td>Testware</td><td>测试过程中产生的所有工件（用例、脚本、数据、报告）</td></tr><tr><td><strong>仿真器/模拟器</strong></td><td>Emulator / Simulator</td><td>模拟真实设备行为的软件</td></tr><tr><td><strong>测试环境</strong></td><td>Test Environment</td><td>执行测试所需的硬件、软件、数据、网络配置</td></tr><tr><td><strong>预发布环境/预生产环境</strong></td><td>Staging / Pre-Production</td><td>模拟生产环境的验证环境</td></tr><tr><td><strong>技术债务</strong></td><td>Technical Debt</td><td>走捷径写的低质量代码，将来需要返工偿还</td></tr><tr><td><strong>代码异味</strong></td><td>Code Smell</td><td>代码中可能存在深层问题的表面迹象</td></tr><tr><td><strong>重构</strong></td><td>Refactoring</td><td>改善代码内部结构，不改变外部行为</td></tr><tr><td><strong>混沌工程</strong></td><td>Chaos Engineering</td><td>主动在生产环境注入故障，验证系统的韧性</td></tr><tr><td><strong>契约测试</strong></td><td>Contract Testing</td><td>验证服务间通信的契约（接口协议）有没有被破坏</td></tr><tr><td><strong>快照测试</strong></td><td>Snapshot Testing</td><td>对 UI/输出的快照做前后对比，发现意外变化</td></tr><tr><td><strong>突变测试</strong></td><td>Mutation Testing</td><td>故意修改代码（注入错误），验证测试用例能不能抓到</td></tr><tr><td><strong>圈复杂度</strong></td><td>Cyclomatic Complexity</td><td>代码中有多少条独立线性路径</td></tr></tbody></table><hr><blockquote><p><strong>参考标准</strong>：ISTQB（International Software Testing Qualifications Board）Glossary v3.7 <strong>相关文档</strong>：<a href="/testing/appendix/test-categories.html">测试分类</a> · <a href="/testing/appendix/test-plan.html">测试计划</a> · <a href="/testing/appendix/test-case.html">测试用例</a> · <a href="/testing/appendix/bug-record.html">缺陷记录</a> · <a href="/testing/appendix/test-report.html">测试报告</a> · <a href="/testing/appendix/release-checklist.html">产品上线</a></p></blockquote>',58)])])}const b=d(o,[["render",s]]);export{c as __pageData,b as default};
